    bars = []  # side, lo, hi, color; contiguous runs on grid edges
    sequences = [('top', grid[0]), ('bottom', grid[-1]),
                 ('left', [grid[r][0] for r in range(h)]),
                 ('right', [grid[r][-1] for r in range(h)])]
    for side, seq in sequences:
        i = 0
        while i < len(seq):
            if seq[i] == bg:
                i += 1
                continue
            color, lo = seq[i], i
            while i + 1 < len(seq) and seq[i + 1] == color:
                i += 1
            bars.append((side, lo, i, color))
            i += 1

    opp = {'top':'bottom', 'bottom':'top', 'left':'right', 'right':'left'}
    def is_bar(r, c):
        return any((s == 'top' and r == 0 and a <= c <= b) or
                   (s == 'bottom' and r == h-1 and a <= c <= b) or
                   (s == 'left' and c == 0 and a <= r <= b) or
                   (s == 'right' and c == w-1 and a <= r <= b)
                   for s, a, b, _ in bars)

    pairs = []
    for bar in bars:
        s, a, b, _ = bar
        other = next((x for x in bars if x[0] == opp[s] and x[2]-x[1] == b-a), None)
        if other is not None:
            pairs.append((bar, other))

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or is_bar(r, c):
                continue
            candidates = []
            for bar, other in pairs:
                side, lo, hi, _ = bar
                if side in ('left', 'right') and lo <= r <= hi:
                    edge_c = 0 if side == 'left' else w-1
                    candidates.append((abs(c-edge_c), bar, other, r-lo))
                elif side in ('top', 'bottom') and lo <= c <= hi:
                    edge_r = 0 if side == 'top' else h-1
                    candidates.append((abs(r-edge_r), bar, other, c-lo))
            if not candidates:
                continue
            _, bar, other, offset = min(candidates, key=lambda x: x[0])
            side, lo, hi, _ = bar
            out[r][c] = 4
            if side in ('left', 'right'):
                edge_c = 0 if side == 'left' else w-1
                step = 1 if edge_c > c else -1
                cc = c + step
                while cc != edge_c:
                    if grid[r][cc] == bg:
                        out[r][cc] = color
                    cc += step
                target_r = other[1] + offset
                opposite_edge = 0 if other[0] == 'left' else w-1
                step = 1 if opposite_edge == 0 else -1
                cc = opposite_edge + step
                while 0 <= cc < w:
                    if grid[target_r][cc] == bg:
                        out[target_r][cc] = color
                    cc += step
            else:
                edge_r = 0 if side == 'top' else h-1
                step = 1 if edge_r > r else -1
                rr = r + step
                while rr != edge_r:
                    if grid[rr][c] == bg:
                        out[rr][c] = color
                    rr += step
                target_c = other[1] + offset
                opposite_edge = 0 if other[0] == 'top' else h-1
                step = 1 if opposite_edge == 0 else -1
                rr = opposite_edge + step
                while 0 <= rr < h:
                    if grid[rr][target_c] == bg:
                        out[rr][target_c] = color
                    rr += step
    return out
